def _failing_once(real, failure, *, calls):
    """Wrap ``real``; raise ``failure`` on the ``calls``-th invocation.

    ``calls`` is a 1-based ordinal or a set of ordinals. The wrapper only
    counts successful entries into the wrapped function (a previous
    injected failure does not consume a later ordinal).
