    ordinals = {calls} if isinstance(calls, int) else set(calls)
    state = {"n": 0}

    def wrapped(*args, **kwargs):
        state["n"] += 1
        if state["n"] in ordinals:
            raise failure
        return real(*args, **kwargs)

    return wrapped

